import { IBackOffOptions } from "exponential-backoff/src/options";
import { SkipFirstDelay } from "exponential-backoff/src/delay/skip-first/skip-first.delay";
import { AlwaysDelay } from "exponential-backoff/src/delay/always/always.delay";
import { IDelay } from "exponential-backoff/src/delay/delay.interface";

export function DelayFactory(options: IBackOffOptions, attempt: number): IDelay {
    const delay = initDelayClass(options);
    delay.setAttemptNumber(attempt);
    return delay;
}

function initDelayClass(options: IBackOffOptions) {
    if (!options.delayFirstAttempt) {
        return new SkipFirstDelay(options);
    }

    return new AlwaysDelay(options);
}